{"message":"Migrate execution and row conversion to supported SQLAlchemy 2.0 APIs.","rationale":"Wrap SQL statements with text() and read results through mappings() to return plain dictionaries ordered by id. Preserve the existing engine.begin() transaction so empty batches work, prior rows persist, and any NOT NULL violation rolls back the entire batch; dependency pins remain unchanged.","files":[{"path":"src/integration.py","content":"from sqlalchemy import text


def upsert_and_list(engine, records):
    with engine.begin() as connection:
        connection.execute(text("CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY, name TEXT NOT NULL)"))
        for record in records:
            connection.execute(text("INSERT INTO items(id, name) VALUES (:id, :name) "
                                    "ON CONFLICT(id) DO UPDATE SET name=excluded.name"), record)
        rows = connection.execute(text("SELECT id, name FROM items ORDER BY id")).mappings().all()
        return [dict(row) for row in rows]
